func And(predicates ...predicate.ScheduleLayer) predicate.ScheduleLayer {
	return predicate.ScheduleLayer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ScheduleLayer) predicate.ScheduleLayer {
	return predicate.ScheduleLayer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ScheduleLayer) predicate.ScheduleLayer {
	return predicate.ScheduleLayer(sql.NotPredicates(p))
}
